// tx3 — W3: West Texas (Marfa), new San Luís places, road events
Object.assign(DISH,{
 chilecol:{n:['红辣椒炖牛肉','Chile colorado (red chile beef)','Chile colorado (carne em chile vermelho)'],ing:'beef',price:13,unlock:true,pref:{ranch:3,trucker:2,oil:1,family:1}}
});
(function(){
const met=id=>!!(S.npc[id]&&S.npc[id].met);
const today=k=>S.flags['tx3_'+k]===dayIndex();
const markToday=k=>{S.flags['tx3_'+k]=dayIndex()};
const ONCE_DAY=k=>()=>today(k)?t(`今天已经来过了`,`You've already done that today`,`Já fizeste isso hoje`):true;
const NIGHTONLY=()=>S.slot===2||t(`只在夜晚`,`Nights only`,`Só à noite`);
const DAYTIME=()=>S.slot<2||t(`天黑了，明天再来`,`It's dark — come back tomorrow`,`Já é noite — volta amanhã`);
const sellLine=r=>r.sold?t(`卖出 ${r.sold} 份，收入 $${r.cash}`,`Sold ${r.sold} portions for $${r.cash}`,`Vendeste ${r.sold} doses por $${r.cash}`):t(`冷藏箱是空的，什么也没卖出去`,`The cooler is empty — you sell nothing`,`A geleira está vazia — não vendes nada`);
const W=()=>S.tripWith;

/* ================= MARFA ================= */
Object.assign(CITIES,{
 marfa:{
  n:t(`马尔法`,`Marfa`,`Marfa`), region:'west', miles:430, trip:'overnight', hotel:140,
  desc:t(`高原沙漠里的小镇，一座粉色的县法院、一群艺术家，和一种没人解释得清的夜光。`,`A high-desert town: a pink courthouse, a colony of artists, and lights at night nobody can explain.`,`Uma vila no deserto alto: um tribunal cor-de-rosa, uma colónia de artistas e umas luzes noturnas que ninguém sabe explicar.`),
  arrive:()=>{const v=S.visited.marfa||0;
   if(v<=1)return [
    t(`过了圣安东尼奥，路就一直往西。树越来越矮，后来只剩下灌木。过佩科斯河的时候你已经开了五个钟头，地图上才走了一半。`,`Past San Antonio the road just goes west. The trees get shorter, then there are only shrubs. By the time you cross the Pecos you're five hours in and barely halfway across the map.`,`Depois de San Antonio a estrada vai sempre para oeste. As árvores encolhem, depois só há arbustos. Quando atravessas o Pecos já levas cinco horas e ainda mal vais a meio do mapa.`),
    t(`下车的时候已经是傍晚。空气又干又凉，海拔一千四百多米，你喘气都觉得轻。离圣鲁伊斯四百三十英里，离里斯本——你算了一下，又不算了。这是你一辈子离家最远的地方，也是离那家店最远的地方。奇怪的是，你心里很静。`,`It's evening when you get out. The air is dry and cool; at over four thousand feet even breathing feels lighter. Four hundred thirty miles from San Luís, and from Lisbon — you start to work it out, then stop. This is the furthest you have ever been from home, and the furthest from the shop. Strangely, everything in you is quiet.`,`Quando sais do carro já é fim de tarde. O ar é seco e fresco; a mais de mil e quatrocentos metros até respirar parece mais leve. Quatrocentas e trinta milhas de San Luís, e de Lisboa — começas a fazer as contas e desistes. Nunca estiveste tão longe de casa, nem tão longe do restaurante. O estranho é que estás em paz.`)];
   return [t(`又回到这片草原。路边几只叉角羚抬起头看你，像一群认出熟人的老邻居。`,`Back on the grassland. A few pronghorn by the road lift their heads, like old neighbours who recognise you.`,`De volta à pradaria. Uns antilocapras à beira da estrada levantam a cabeça, como vizinhos antigos que te reconhecem.`)]},
  locs:[
   {id:'downtown', n:t(`马尔法市中心`,`Downtown Marfa`,`Centro de Marfa`), acts:[
    {id:'walk', n:t(`在小镇里走走`,`Walk the town`,`Passear pela vila`), cost:2, tip:t(`县法院、旧军营里的铝盒子、穿城而过的火车`,`The courthouse, the aluminum boxes at the old fort, the trains through town`,`O tribunal, as caixas de alumínio no antigo quartel, os comboios`),
     run:()=>({title:t(`马尔法市中心`,`Downtown Marfa`,`Centro de Marfa`),meta:t(`西德州 · 高原沙漠`,`West Texas · high desert`,`Oeste do Texas · deserto alto`),
      text:[t(`镇子小得十分钟就能走穿。宽得过分的街道，土坯墙，几家没有招牌的画廊。街尽头是 1886 年建的县法院，浅粉色的墙，顶上一个圆顶，像有人把一块婚礼蛋糕放在了沙漠中间。`,`You can cross the whole town in ten minutes. Streets far too wide, adobe walls, a few galleries with no signs. At the end of the street stands the county courthouse, built in 1886: pale pink walls and a dome, as if someone had set a wedding cake down in the middle of the desert.`,`Atravessa-se a vila inteira em dez minutos. Ruas largas demais, paredes de adobe, umas galerias sem tabuleta. Ao fundo, o tribunal do condado, de 1886: paredes cor-de-rosa pálido e uma cúpula, como se alguém tivesse pousado um bolo de casamento no meio do deserto.`)],
      choices:[
       {t:t(`去城南的旧军营看铝盒子`,`Go see the aluminum boxes at the old fort`,`Ir ver as caixas de alumínio no antigo quartel`),fx:()=>{stat('saud',-2);stat('charme',1);stat('oficio',1)},next:()=>say(t(`一百个铝盒子`,`A hundred aluminum boxes`,`Cem caixas de alumínio`),[
        t(`七十年代，一位叫唐纳德·贾德的纽约雕塑家搬到这里，把废弃的军营改成了展厅。两座旧炮兵棚里，整整齐齐摆着一百个铝盒子，外面一样大，里面的切法各不相同。`,`In the seventies a New York sculptor named Donald Judd moved here and turned the abandoned army post into a place to show work. In two old artillery sheds stand a hundred aluminum boxes in rows, all the same size outside, each one cut differently inside.`,`Nos anos setenta, um escultor de Nova Iorque chamado Donald Judd mudou-se para cá e transformou o quartel abandonado num espaço de exposição. Em dois antigos armazéns de artilharia alinham-se cem caixas de alumínio, iguais por fora, cada uma cortada de maneira diferente por dentro.`),
        t(`窗外是草原。云一过，光一变，盒子就变成另外一百个盒子。你站了很久。你想起建筑系第一年老师说的话：房子不是墙，是墙之间的光。你没读完，但这句话你一直带着。`,`Outside the windows is grassland. A cloud passes, the light shifts, and the boxes become a hundred other boxes. You stand there a long time. You remember what your first-year architecture professor said: a building isn't walls, it's the light between them. You never finished the degree. You kept the sentence.`,`Lá fora, a pradaria. Passa uma nuvem, a luz muda, e as caixas tornam-se outras cem caixas. Ficas muito tempo parado. Lembras-te do que o professor do primeiro ano de arquitetura dizia: uma casa não são paredes, é a luz entre elas. Não acabaste o curso. A frase ficou contigo.`)],t(`乡愁 −2 · 魅力 +1 · 手艺 +1`,`Homesickness −2 · Charm +1 · Craft +1`,`Saudade −2 · Charme +1 · Ofício +1`))},
       
       {t:t(`在铁道边等一列火车过去`,`Wait by the tracks for a train`,`Esperar um comboio junto à linha`),fx:()=>{stat('saud',3)},next:()=>say(t(`货运火车`,`Freight train`,`Comboio de mercadorias`),t(`铁轨从镇子正中间穿过去。火车来的时候整条街都在抖，一节，两节，你数到一百一十就不数了。它往西去，往埃尔帕索，往加州。你想起小时候在阿尔坎塔拉看火车，也是这样一直数。`,`The tracks run straight through the middle of town. When the train comes the whole street shakes — one car, two cars; you stop counting at a hundred and ten. It's heading west, toward El Paso, toward California. You remember watching trains at Alcântara as a boy, counting just like this.`,`A linha atravessa a vila pelo meio. Quando o comboio passa, a rua inteira treme — um vagão, dois; paras de contar aos cento e dez. Vai para oeste, para El Paso, para a Califórnia. Lembras-te de ver os comboios em Alcântara em miúdo, a contar assim mesmo.`),t(`乡愁 +3`,`Homesickness +3`,`Saudade +3`))}]})},
    {id:'popup', n:t(`给艺术圈办一场快闪晚餐`,`Pop-up dinner for the art crowd`,`Jantar pop-up para o pessoal das artes`), cost:3, req:()=>NIGHTONLY()===true?ONCE_DAY('mpop')():NIGHTONLY(), tip:t(`从库存卖出，价格翻倍；也许有人请你做外烩`,`Sells from your stock at nearly double; someone might commission you`,`Vende do teu stock a quase o dobro; talvez alguém te encomende um jantar`),
     run:()=>{markToday('mpop');const r=popupSell(14,1.8);S.online+=r.sold?2:0;
      const seen=!!S.flags.tx3_commission;
      return {title:t(`院子里的长桌`,`The long table in the courtyard`,`A mesa comprida no pátio`),meta:sellLine(r),
       text:[t(`一家画廊把后院借给你。土坯墙上挂着一串灯泡，长桌坐了二十个人：纽约来的策展人、穿工装裤的雕塑家，还有两个闻着烟过来的牧场主。`,`A gallery lends you its back courtyard. A string of bulbs on the adobe wall, twenty people at the long table: a curator from New York, a sculptor in overalls, and two ranchers who just followed the smoke.`,`Uma galeria empresta-te o pátio das traseiras. Uma fiada de lâmpadas na parede de adobe, vinte pessoas na mesa comprida: uma curadora de Nova Iorque, um escultor de jardineiras e dois rancheiros que vieram atrás do fumo.`),
        t(`策展人吃了一口，闭上眼睛：“这不是菜，这是一个地方。”牧场主说：“这是好吃。”你觉得两个人说的是同一件事。`,`The curator takes a bite and closes her eyes. "This isn't a dish, it's a place." One rancher says, "It's good." You think they're saying the same thing.`,`A curadora prova e fecha os olhos. «Isto não é um prato, é um lugar.» Um rancheiro diz: «Está bom.» Achas que estão os dois a dizer o mesmo.`)],
       choices:[
        {t:t(`接下她的委托：下个月开幕式的晚宴`,`Take her commission: dinner for next month's opening`,`Aceitar a encomenda: o jantar da inauguração do mês que vem`),req:()=>seen?t(`已经接过委托了`,`Commission already taken`,`Encomenda já aceite`):S.stats.oficio>=45||NEED(t(`手艺 45`,`Craft 45`,`Ofício 45`)),fx:()=>{S.flags.tx3_commission=1;S.cash+=450;S.wk.rev+=450;S.online+=5;S.rep+=2;stat('oficio',2)},next:()=>say(t(`委托`,`The commission`,`A encomenda`),t(`她当场写了一张支票，又加了一句：“菜单你定。我只要求一件事——别做成德州菜，也别做成葡萄牙菜，做成你。”`,`She writes a check on the spot and adds, "You pick the menu. One condition: don't make it Texan and don't make it Portuguese. Make it you."`,`Passa-te um cheque ali mesmo e acrescenta: «A ementa é tua. Só uma condição: não faças comida texana nem portuguesa. Faz-te a ti.»`),t(`现金 +$450 · 线上评分 +5 · 口碑 +2 · 手艺 +2`,`Cash +$450 · Online rating +5 · Reputation +2 · Craft +2`,`Dinheiro +$450 · Avaliação online +5 · Reputação +2 · Ofício +2`))},
        
        {t:t(`收桌，早点睡`,`Clear the table and turn in`,`Levantar a mesa e ir dormir`)}]}}},
    {id:'chile', n:t(`铁道边的卷饼窗口`,`The burrito window by the tracks`,`O postigo dos burritos junto à linha`), cost:2, tip:t(`学一道西德州的菜`,`Learn a West Texas dish`,`Aprender um prato do Oeste do Texas`),
     run:()=>{const known=!!S.flags.dish_chilecol;
      return {title:t(`红辣椒`,`Red chile`,`Chile vermelho`),meta:t(`离墨西哥边境六十英里`,`Sixty miles from the border`,`A sessenta milhas da fronteira`),
       text:[t(`铁道边有个只开一扇小窗的厨房，一位从奇瓦瓦来的老太太在里面忙。窗台上晒着一串串暗红色的干辣椒。她递给你一碗炖牛肉，汤是砖红色的，不怎么辣，但很深，像傍晚的山。`,`By the tracks there's a kitchen with nothing but one small window, and an old woman from Chihuahua working inside. Strings of dark red dried chiles hang drying on the sill. She hands you a bowl of beef stew, brick-red, not very hot but very deep, like the mountains at dusk.`,`Junto à linha há uma cozinha que é só um postigo, e lá dentro uma senhora de Chihuahua. No parapeito secam réstias de malaguetas secas, vermelho-escuro. Dá-te uma tigela de carne estufada, cor de tijolo, pouco picante mas muito funda, como as montanhas ao fim da tarde.`),
        known?t(`她认出你：“又是你，葡萄牙人。辣椒泡够时间了吗？”`,`She recognises you. "You again, Portuguese. Are you soaking the chiles long enough?"`,`Reconhece-te. «Outra vez tu, português. Deixas as malaguetas de molho o tempo suficiente?»`):t(`你问她怎么做。她看了你一眼：“你妈妈做菜的时候，会告诉你放多少盐吗？”`,`You ask how she makes it. She looks at you. "When your mother cooks, does she tell you how much salt?"`,`Perguntas-lhe como se faz. Ela olha para ti. «Quando a tua mãe cozinha, diz-te quanto sal põe?»`)],
       choices:[
        {t:t(`说实话：不会，她只说“放到对为止”`,`Tell the truth: no, she just says "until it's right"`,`Dizer a verdade: não, ela só diz «até estar bom»`),req:()=>known?t(`已经学会了`,`Already learned`,`Já aprendeste`):true,fx:()=>{learnDish('chilecol');stat('oficio',3);stat('saud',2)},next:()=>say(t(`红辣椒炖牛肉`,`Chile colorado`,`Chile colorado`),t(`她笑了，打开后门让你进去。干辣椒去籽、烤一下、用热水泡软、打成泥，牛肉切块慢慢炖。“放到对为止，”她说，“你妈妈是对的。”`,`She laughs and opens the back door. Seed the dried chiles, toast them, soak them soft in hot water, blend them, and braise the cubed beef slow. "Until it's right," she says. "Your mother is right."`,`Ela ri-se e abre-te a porta das traseiras. Tirar as sementes às malaguetas, tostá-las, amolecê-las em água quente, triturar, e estufar a carne aos cubos devagar. «Até estar bom», diz ela. «A tua mãe tem razão.»`),t(`学会：红辣椒炖牛肉（菜单里可选）· 手艺 +3 · 乡愁 +2`,`Learned: chile colorado (now on the menu list) · Craft +3 · Homesickness +2`,`Aprendeste: chile colorado (já na lista da ementa) · Ofício +3 · Saudade +2`))},
        {t:t(`买两大串干辣椒带回店里`,`Buy two big strings of dried chiles for the shop`,`Comprar duas réstias grandes de malaguetas para o restaurante`),req:MONEY(25),fx:()=>{S.cash-=25;S.wk.spend+=25;stat('tex',2);S.rep+=1},next:()=>say(t(`干辣椒`,`Dried chiles`,`Malaguetas secas`),t(`你把辣椒挂在店里收银台后面。厄尔说看着像圣诞节。贝托说看着像他外婆家。`,`You hang the chiles behind the register at the shop. Earl says they look like Christmas. Beto says they look like his grandmother's house.`,`Penduras as malaguetas atrás da caixa no restaurante. O Earl diz que parece Natal. O Beto diz que parece a casa da avó dele.`),t(`−$25 · 德州味 +2 · 口碑 +1`,`−$25 · Texanness +2 · Reputation +1`,`−$25 · Texanidade +2 · Reputação +1`))},
        {t:t(`坐在台阶上把那碗吃完`,`Sit on the step and finish the bowl`,`Sentar no degrau e acabar a tigela`),fx:()=>stat('tex',1)}]}}}
   ]},
   {id:'prada', n:t(`公路上的普拉达·马尔法`,`Prada Marfa, out on the highway`,`Prada Marfa, na estrada`), acts:[
    {id:'look', n:t(`去看那家开不了门的店`,`See the shop that never opens`,`Ver a loja que nunca abre`), cost:2, tip:t(`往西北开半个钟头，瓦伦丁镇外`,`Half an hour northwest, outside Valentine`,`Meia hora para noroeste, à saída de Valentine`),
     run:()=>{const w=W();
      const ch=[
       {t:t(`隔着玻璃看很久`,`Look through the glass a long time`,`Ficar muito tempo a olhar pela montra`),fx:()=>{stat('saud',2);stat('oficio',1)},next:()=>say(t(`橱窗`,`The window`,`A montra`),t(`你想到若泽的店。它没有这么好看，门把手是坏的，冷柜会响。但它的门每天早上都开。你突然很想快点回去，把那扇门打开。`,`You think of José's shop. It's nowhere near this pretty — the door handle is broken, the cooler hums. But its door opens every morning. Suddenly you want to get back and open it.`,`Pensas no restaurante do José. Não é tão bonito — o puxador está partido, a arca frigorífica zumbe. Mas a porta abre todas as manhãs. De repente tens vontade de voltar e abri-la.`),t(`乡愁 +2 · 手艺 +1`,`Homesickness +2 · Craft +1`,`Saudade +2 · Ofício +1`))},
       {t:t(`拍一张发给鲁伊：“我在德州开了分店”`,`Send Rui a photo: "Opened a second branch in Texas"`,`Mandar uma foto ao Rui: «Abri uma filial no Texas»`),fx:()=>{stat('saud',-1);stat('charme',1);S.online+=1},next:()=>say(t(`鲁伊的回复`,`Rui replies`,`O Rui responde`),t(`里斯本已经半夜了，鲁伊还是秒回：“只卖右脚的鞋？那很适合你，你从小就只会往一个方向跑。”后面跟着三个笑哭的表情，和一句：“妈今天好多了。”`,`It's past midnight in Lisbon and Rui answers in seconds: "Right shoes only? Suits you. You've only ever run in one direction." Three crying-laughing faces, then: "Mom's much better today."`,`Já passa da meia-noite em Lisboa e o Rui responde num segundo: «Só sapatos do pé direito? Tem a ver contigo, sempre fugiste só para um lado.» Três caras a chorar a rir, e depois: «A mãe hoje está muito melhor.»`),t(`乡愁 −1 · 魅力 +1 · 线上评分 +1`,`Homesickness −1 · Charm +1 · Online rating +1`,`Saudade −1 · Charme +1 · Avaliação online +1`))}];
      if(w)ch.unshift({t:t(`和${SH(w)}在假橱窗前拍一张合照`,`Take a picture with ${SH(w)} in front of the fake window`,`Tirar uma foto com ${SH(w)} em frente à montra falsa`),fx:()=>{addLike(w,1);addTrust(w,0.5);stat('charme',1)},next:()=>say(t(`合照`,`The picture`,`A fotografia`),[t(`${SH(w)}把手机举得高高的，想把整片沙漠都装进去。拍了十几张，最后留下的那张里，你们俩都没看镜头，在看对方笑。`,`${SH(w)} holds the phone up high, trying to fit the whole desert in. A dozen shots; the one you keep has neither of you looking at the camera — you're laughing at each other.`,`${SH(w)} levanta o telemóvel bem alto, a tentar caber o deserto inteiro. Uma dúzia de fotos; a que guardam é uma em que nenhum dos dois olha para a câmara — estão a rir-se um para o outro.`),t(`“这家店永远不开门，”${SH(w)}说，“你那家天天开。我比较喜欢你那家。”`,`"This store never opens," ${SH(w)} says. "Yours opens every day. I like yours better."`,`«Esta loja nunca abre», diz ${SH(w)}. «A tua abre todos os dias. Gosto mais da tua.»`)],t(`${SH(w)}好感 +1 · 信任 +0.5 · 魅力 +1`,`${SH(w)} affection +1 · trust +0.5 · Charm +1`,`${SH(w)}: afeto +1 · confiança +0,5 · Charme +1`))});
      return {title:t(`普拉达·马尔法`,`Prada Marfa`,`Prada Marfa`),meta:t(`90 号公路 · 瓦伦丁镇外`,`US 90 · outside Valentine`,`US 90 · à saída de Valentine`),
       text:[t(`方圆几十英里只有草、铁丝网和电线杆，然后它突然出现在公路边：一间白色的土坯小屋，大玻璃窗，里面亮着灯，摆着名牌皮包和高跟鞋，像从纽约第五大道上掉下来的一块。`,`For miles there's only grass, barbed wire and telephone poles, and then there it is beside the road: a small white adobe building with big plate-glass windows, lit up inside, handbags and heels on display, like a piece of Fifth Avenue dropped from the sky.`,`Durante milhas só há erva, arame farpado e postes, e de repente ali está, à beira da estrada: uma casinha branca de adobe, montras enormes, luz lá dentro, malas e saltos altos em exposição, como um bocado da Quinta Avenida caído do céu.`),
        t(`门是锁死的，永远不会开。这是 2005 年两位北欧艺术家做的作品，据说里面的鞋全是右脚的。`,`The door is sealed and will never open. Two Scandinavian artists made it in 2005. They say the shoes are all right feet.`,`A porta está selada e nunca vai abrir. Dois artistas escandinavos fizeram-na em 2005. Dizem que os sapatos são todos do pé direito.`)],
       choices:ch}}},
    {id:'valentine', n:t(`瓦伦丁镇的小邮局`,`The little post office in Valentine`,`A pequena estação de correios de Valentine`), cost:1, req:DAYTIME, tip:t(`寄一张明信片`,`Mail a postcard`,`Enviar um postal`),
     run:()=>({title:t(`瓦伦丁`,`Valentine`,`Valentine`),meta:t(`人口不到一百`,`Population under a hundred`,`Menos de cem habitantes`),
      text:[t(`瓦伦丁镇只有几栋房子、一条铁道和一个小邮局。因为镇名的意思是“情人”，每年二月，全国都有人把情人卡寄到这里，请邮局盖一个这里的邮戳再转出去。`,`Valentine is a few houses, a railroad and a tiny post office. Because of the name, every February people from all over the country mail their valentines here to get the town's postmark before they go on.`,`Valentine são umas casas, uma linha de comboio e uma estação de correios minúscula. Por causa do nome, todos os fevereiros chega gente de todo o país a enviar postais de São Valentim para cá, para levarem o carimbo da terra.`),
       inSeason(33,36)?t(`现在正是二月。柜台上堆着一摞一摞粉红色的信封，邮局阿姨盖章盖得手腕都酸了。`,`It's February now. Pink envelopes are stacked on the counter, and the woman behind it has stamped until her wrist aches.`,`Estamos em fevereiro. Há pilhas de envelopes cor-de-rosa no balcão, e a senhora dos correios já tem o pulso dorido de carimbar.`):t(`现在不是二月，邮局里只有一台电扇和一只睡觉的猫。`,`It isn't February, so the post office holds only a fan and a sleeping cat.`,`Não é fevereiro, por isso nos correios só há uma ventoinha e um gato a dormir.`),
       t(`你买了一张明信片，上面是一片空荡荡的草原。你拿着笔，想起若泽那十二封没寄出去的信。`,`You buy a postcard of an empty grassland. Pen in hand, you think of José's twelve letters that never got sent.`,`Compras um postal com uma pradaria vazia. De caneta na mão, pensas nas doze cartas do José que nunca foram enviadas.`)],
      choices:[
       {t:t(`写给妈妈，当场寄掉`,`Write to Mom and mail it right now`,`Escrever à mãe e enviar logo`),fx:()=>{S.cash-=2;stat('saud',-3);S.flags.tx3_postcard=1},next:()=>say(t(`寄出去了`,`Sent`,`Enviado`),t(`你只写了三行：“我很好。这里很远，很安静。我会回家看你。”你把它投进信箱，听见它落下去的声音。若泽缺的就是这一声。`,`You write only three lines: "I'm fine. It's very far and very quiet here. I'll come home to see you." You drop it in the slot and hear it land. That small sound is what José never had.`,`Escreves só três linhas: «Estou bem. Isto é muito longe e muito sossegado. Vou a casa ver-te.» Metes no marco e ouves o postal cair. Esse barulhinho foi o que faltou ao José.`),t(`乡愁 −3 · −$2`,`Homesickness −3 · −$2`,`Saudade −3 · −$2`))},
       
       {t:t(`写好了，放进口袋`,`Write it, and keep it in your pocket`,`Escrever e guardar no bolso`),fx:()=>{stat('saud',4)},next:()=>say(t(`没寄的明信片`,`The unsent postcard`,`O postal por enviar`),t(`你把明信片对折放进上衣口袋。你知道这样不对，但你今天还没准备好。你们家的人，好像都是这样。`,`You fold the postcard into your shirt pocket. You know it's wrong; you just aren't ready today. People in your family all seem to be like this.`,`Dobras o postal e guardas no bolso da camisa. Sabes que não está certo; só que hoje não estás pronto. Na tua família parece que são todos assim.`),t(`乡愁 +4`,`Homesickness +4`,`Saudade +4`))}]})}
   ]},
   {id:'lights', n:t(`马尔法神秘光观景台`,`Marfa Lights viewing area`,`Miradouro das luzes de Marfa`), acts:[
    {id:'watch', n:t(`等那种光`,`Wait for the lights`,`Esperar pelas luzes`), cost:2, req:NIGHTONLY, tip:t(`镇东九英里的公路边`,`Nine miles east of town on the highway`,`A nove milhas a leste da vila, na estrada`),
     run:()=>{const w=W(),seen=Math.random()<0.5;if(seen)S.flags.tx3_lights=(S.flags.tx3_lights||0)+1;
      const ch=[
       {t:t(`不去管它是什么，就看着`,`Don't decide what it is. Just watch`,`Não decidir o que é. Só olhar`),fx:()=>{stat('saud',-2);S.energy=Math.min(10,S.energy+1)},next:()=>say(t(`看着`,`Watching`,`A olhar`),t(`你不再想解释。黑暗那么大，光那么小，你那么小，店里的账、特拉维斯的笑、妈妈的病，在这片草原上也都那么小。不是不重要，是终于放得下了。`,`You stop trying to explain it. The dark is so big, the light so small, you so small — the shop's books, Travis's smile, your mother's illness, all of it small out here on the flat. Not unimportant. Just, finally, something you can set down.`,`Deixas de querer explicar. O escuro é tão grande, a luz tão pequena, tu tão pequeno — as contas do restaurante, o sorriso do Travis, a doença da mãe, tudo pequeno nesta planície. Não é que não importe. É que finalmente consegues pousá-lo.`),t(`乡愁 −2 · 精力 +1`,`Homesickness −2 · Energy +1`,`Saudade −2 · Energia +1`))},
       {t:t(`回车里开暖气，等到困了`,`Get back in the truck, heat on, and wait until you\'re sleepy`,`Voltar para o carro, aquecimento ligado, e esperar até teres sono`),fx:()=>{S.energy=Math.min(10,S.energy+1)}}];
      if(w)ch.unshift({t:t(`和${SH(w)}靠在车上，一起等`,`Lean on the truck with ${SH(w)} and wait together`,`Encostar-te ao carro com ${SH(w)} e esperar juntos`),fx:()=>{addTrust(w,1);addLike(w,0.5);stat('saud',-1)},next:()=>say(t(`等光的人`,`Waiting for the lights`,`À espera das luzes`),[t(`夜里冷了，你们共用一件外套。很长时间谁都没说话。后来${SH(w)}小声问：“你在想里斯本吗？”`,`The night turns cold and you share one jacket. For a long time nobody speaks. Then ${SH(w)} asks quietly, "Are you thinking about Lisbon?"`,`A noite arrefece e partilham um casaco. Durante muito tempo ninguém fala. Depois ${SH(w)} pergunta baixinho: «Estás a pensar em Lisboa?»`),t(`你说实话：“在想。也在想圣鲁伊斯。我好像第一次两个地方同时想，心里不打架。”${SH(w)}没说什么，只是把外套往你那边拉了拉。`,`You tell the truth. "I am. And about San Luís. It's the first time I've thought about both at once without them fighting." ${SH(w)} says nothing, just pulls the jacket a little further over you.`,`Dizes a verdade: «Estou. E em San Luís. É a primeira vez que penso nas duas ao mesmo tempo sem que lutem uma com a outra.» ${SH(w)} não diz nada; só puxa o casaco um pouco mais para o teu lado.`)],t(`${SH(w)}信任 +1 · 好感 +0.5 · 乡愁 −1`,`${SH(w)} trust +1 · affection +0.5 · Homesickness −1`,`${SH(w)}: confiança +1 · afeto +0,5 · Saudade −1`))});
      return {title:t(`马尔法神秘光`,`The Marfa Lights`,`As luzes de Marfa`),meta:seen?t(`今晚，它们出现了`,`Tonight, they came`,`Esta noite apareceram`):t(`今晚，什么也没有`,`Tonight, nothing`,`Esta noite, nada`),
       text:[t(`公路边有一个石头砌的观景台，十几个人裹着毯子，朝南望着黑漆漆的平原和远处的奇纳蒂山。据说 1883 年一个赶牛的牛仔第一次看见了这种光，之后一百多年，有人说是车灯，有人说是空气折射，有人说是鬼。`,`Beside the highway there's a stone viewing platform. A dozen people in blankets look south across the black flat toward the Chinati Mountains. The story goes that a cowhand first saw the lights in 1883; in the century and more since, people have called them headlights, mirages, ghosts.`,`À beira da estrada há um miradouro de pedra. Uma dúzia de pessoas embrulhadas em mantas olha para sul, para a planície negra e para as montanhas Chinati. Diz-se que um vaqueiro viu as luzes pela primeira vez em 1883; desde então chamaram-lhes faróis, miragens, fantasmas.`),
        seen?t(`快十点的时候，地平线上亮起一颗橙色的光点，分成两颗，飘了一会儿，合上，又灭了。有个小孩说“哇”。没有人拍到。`,`Near ten, an orange point of light rises on the horizon, splits in two, drifts, joins again, and goes out. A child says "whoa." Nobody gets it on camera.`,`Perto das dez, acende-se um ponto cor de laranja no horizonte, divide-se em dois, flutua, junta-se e apaga-se. Uma criança diz «uau». Ninguém consegue filmar.`):t(`你等到十一点，只看见远处卡车的车灯和满天的星星。旁边有人说：“没看见也算来过。”`,`You wait until eleven and see only far-off truck headlights and a sky full of stars. Someone beside you says, "Not seeing 'em still counts."`,`Esperas até às onze e só vês faróis de camiões ao longe e o céu cheio de estrelas. Alguém ao teu lado diz: «Não as ver também conta.»`)],
       choices:ch}}},
    {id:'coffee', n:t(`给等光的人卖热咖啡和烤肉`,`Sell hot coffee and grill to the light-watchers`,`Vender café quente e grelhados a quem espera as luzes`), cost:2, req:()=>NIGHTONLY()===true?ONCE_DAY('mcof')():NIGHTONLY(), tip:t(`小炭炉 + 冷藏箱，从库存卖`,`A little charcoal grill and the cooler — sells from stock`,`Um fogareiro e a geleira — vende do stock`),
     run:()=>{markToday('mcof');const r=popupSell(8,1.3);if(r.sold)S.rep+=1;
      return say(t(`观景台边的小炉子`,`A little grill by the platform`,`Um fogareiro junto ao miradouro`),[
       t(`你在停车场边上支起一个小炭炉。沙漠夜里只有十度，烟和肉香飘出去，等光的人一个接一个转过头来。`,`You set up a small charcoal grill at the edge of the lot. The desert night is barely fifty degrees; the smoke drifts out and the light-watchers turn around one after another.`,`Montas um fogareiro na ponta do parque. A noite no deserto está nos dez graus; o fumo espalha-se e quem espera as luzes vai-se virando, um a um.`),
       pick([t(`一个骑摩托横穿美国的德国人吃完说，他在这条路上走了三千英里，这是第一口热的。`,`A German riding a motorcycle across America says he's come three thousand miles and this is the first hot thing he's eaten.`,`Um alemão a atravessar a América de mota diz que fez três mil milhas e é a primeira coisa quente que come.`)]),
       sellLine(r)],r.sold?t(`口碑 +1`,`Reputation +1`,`Reputação +1`):'')}}
   ]},
   {id:'sky', n:t(`戴维斯山与夜空`,`The Davis Mountains and the night sky`,`As montanhas Davis e o céu noturno`), acts:[
    {id:'stars', n:t(`上山看星星`,`Drive up for the stars`,`Subir para ver as estrelas`), cost:3, req:NIGHTONLY, tip:t(`山顶有大学的天文台`,`A university observatory sits on the mountaintop`,`No cimo há um observatório universitário`),
     run:()=>({title:t(`全美最暗的夜空之一`,`One of the darkest skies in America`,`Um dos céus mais escuros da América`),meta:t(`戴维斯山 · 天文台`,`Davis Mountains · the observatory`,`Montanhas Davis · o observatório`),
      text:[t(`往北开一个小时，路在山里绕来绕去，山顶上是大学的天文台，白色的圆顶在月光下像几只蛋。`,`An hour north the road winds into the mountains. On top sits the university observatory, its white domes like eggs in the moonlight.`,`Uma hora para norte, a estrada serpenteia pela serra. No cimo fica o observatório da universidade, as cúpulas brancas como ovos ao luar.`),
       t(`银河不是一条线，是一整片撒开的盐。讲解员说你现在看到的有些光，是几千年前出发的。你想：那若泽离开里斯本的那一年，也就是昨天。`,`The Milky Way isn't a line; it's a whole spilled field of salt. The guide says some of the light you're seeing left its star thousands of years ago. You think: then the year José left Lisbon was just yesterday.`,`A Via Láctea não é uma linha; é um campo inteiro de sal entornado. O guia diz que parte da luz que vês saiu da estrela há milhares de anos. Pensas: então o ano em que o José deixou Lisboa foi ontem.`)],
      choices:[
       {t:t(`问讲解员，从这里能不能看见葡萄牙那边的星星`,`Ask the guide if you can see Portugal's stars from here`,`Perguntar ao guia se daqui se veem as estrelas de Portugal`),fx:()=>{stat('saud',-3);stat('charme',1)},next:()=>say(t(`同一片天`,`The same sky`,`O mesmo céu`),t(`她笑了，把激光笔指向北极星：“里斯本和这里差不多一个纬度。你妈妈今晚抬头，看见的就是这颗，只是比你早六个小时。”你看了很久，像看着一扇开着的窗。`,`She laughs and points her laser at the North Star. "Lisbon's at about the same latitude as here. If your mom looks up tonight, that's the one she sees — six hours ahead of you." You look at it a long time, like an open window.`,`Ela ri-se e aponta o laser à Estrela Polar. «Lisboa está mais ou menos à mesma latitude. Se a tua mãe olhar para cima esta noite, vê esta — seis horas antes de ti.» Ficas muito tempo a olhar, como para uma janela aberta.`),t(`乡愁 −3 · 魅力 +1`,`Homesickness −3 · Charm +1`,`Saudade −3 · Charme +1`))},
       {t:t(`一个人走到停车场尽头，关掉手电`,`Walk alone to the end of the lot and switch off your flashlight`,`Ir sozinho até ao fim do parque e apagar a lanterna`),fx:()=>{stat('saud',2);stat('tex',2);S.energy=Math.min(10,S.energy+2)},next:()=>say(t(`黑`,`Dark`,`Escuro`),t(`黑得你看不见自己的手。风从山下的草原吹上来，什么味道都没有。你在心里对若泽说了一句话，是你一直没说出口的那句。没有人听见。说完你觉得轻了。`,`So dark you can't see your own hand. The wind comes up off the grassland and smells of nothing. In your head you say one thing to José — the thing you've never said out loud. Nobody hears it. Afterwards you feel lighter.`,`Tão escuro que não vês a tua mão. O vento sobe da pradaria e não cheira a nada. Por dentro, dizes uma coisa ao José — aquela que nunca disseste em voz alta. Ninguém ouve. Depois sentes-te mais leve.`),t(`乡愁 +2 · 德州味 +2 · 精力 +2`,`Homesickness +2 · Texanness +2 · Energy +2`,`Saudade +2 · Texanidade +2 · Energia +2`))}]})},
    {id:'beef', n:t(`路边牧场买高原草饲牛`,`Buy high-desert grass-fed beef from a roadside ranch`,`Comprar vaca de pasto a um rancho à beira da estrada`), cost:2, req:()=>DAYTIME()===true?ONCE_DAY('mbeef')():DAYTIME(), tip:t(`牛肉 10 份，七折`,`10 units of beef at 70% price`,`10 unidades de vaca a 70% do preço`),
     run:()=>{markToday('mbeef');const c=cityBuy('beef',10,0.7);
      return {title:t(`铁丝网后面的牧场`,`The ranch behind the barbed wire`,`O rancho atrás do arame farpado`),meta:c?t(`牛肉 +10 · −$${c}`,`Beef +10 · −$${c}`,`Vaca +10 · −$${c}`):t(`钱不够`,`Not enough money`,`Não tens dinheiro`),
       text:[t(`去天文台的路上有个牧场，门口一块手写的木牌：“草饲牛肉，冻好的，敲门。”牧场主是个瘦高的女人，她说这里的牛走几英里才吃得饱一肚子草，所以肉紧，味道重。`,`On the road to the observatory there's a ranch with a hand-painted sign at the gate: "Grass-fed beef, frozen, knock." The rancher is a tall thin woman. She says cattle out here walk miles to fill up on grass, so the meat is tight and full of flavour.`,`A caminho do observatório há um rancho com uma tabuleta pintada à mão no portão: «Carne de pasto, congelada, bata à porta.» A rancheira é uma mulher alta e magra. Diz que aqui as vacas andam milhas para encher a barriga de erva, por isso a carne é firme e cheia de sabor.`),
        c?t(`你把十份牛肉塞满冷藏箱。她又多送了你一袋牛骨：“熬汤。别跟别人说我送的。”`,`You pack ten cuts into the cooler. She throws in a bag of bones: "For stock. Don't tell anyone I gave you those."`,`Enches a geleira com dez peças. Ela ainda te dá um saco de ossos: «Para o caldo. Não digas a ninguém que fui eu.»`):t(`你数了数钱包，不够。她耸耸肩：“下次来。牛不会跑。”`,`You count your wallet. Not enough. She shrugs. "Next time. Cows ain't going anywhere."`,`Contas a carteira. Não chega. Ela encolhe os ombros: «Para a próxima. As vacas não fogem.»`)],
       choices:[
        
        {t:t(`道谢上路`,`Thank her and get going`,`Agradecer e seguir caminho`)}]}}}
   ]}
  ]
 }
});

/* ================= SAN LUÍS: new places ================= */
EXTRA_LOCS.push(
 {id:'feedstore', n:t(`饲料店`,`The feed store`,`A loja de rações`), open:()=>S.week>=2, acts:[
  {id:'tx3eggs', n:t(`买农场鸡蛋和黄油（五五折）`,`Buy farm eggs and butter (55% price)`,`Comprar ovos e manteiga da quinta (55% do preço)`), cost:1, req:ONCE_DAY('eggs'), tip:t(`乳品 12 份，便宜`,`12 units of dairy, cheap`,`12 unidades de lacticínios, barato`),
   run:()=>{markToday('eggs');const c=cityBuy('dairy',12,0.55);
    return say(t(`饲料店`,`The feed store`,`A loja de rações`),[
     t(`饲料店在铁道边，铁皮屋顶，门口堆着一袋袋玉米和矿物舔砖。柜台边的冷柜里放着附近农家的鸡蛋，蛋壳上还粘着稻草。`,`The feed store sits by the railroad, tin roof, sacks of corn and mineral blocks stacked by the door. By the counter a cooler holds eggs from nearby farms, straw still stuck to the shells.`,`A loja de rações fica junto à linha do comboio, telhado de zinco, sacos de milho e blocos de sal à porta. Junto ao balcão, uma arca com ovos das quintas vizinhas, ainda com palha nas cascas.`),
     pick([t(`收银的老头说若泽以前每周来，买鸡蛋，也买一袋鸡饲料，“他说是喂后院的鸽子。镇上谁也没见过那些鸽子。”`,`The old man at the register says José came every week for eggs and a bag of chicken feed. "Said it was for the pigeons out back. Nobody in town ever saw those pigeons."`,`O velho da caixa diz que o José vinha todas as semanas buscar ovos e um saco de ração. «Dizia que era para os pombos lá de trás. Ninguém na vila viu esses pombos.»`)]),
     c?t(`你拎走了十二份鸡蛋和黄油，只花了 $${c}。做蛋挞的成本一下子低了一截。`,`You walk out with twelve units of eggs and butter for just $${c}. Your custard tarts just got a lot cheaper.`,`Sais com doze unidades de ovos e manteiga por apenas $${c}. Os pastéis de nata acabaram de ficar bem mais baratos.`):t(`你钱不够，只好空手出来。`,`You don't have enough money and leave empty-handed.`,`Não tens dinheiro suficiente e sais de mãos vazias.`)],c?t(`乳品 +12 · −$${c}`,`Dairy +12 · −$${c}`,`Lacticínios +12 · −$${c}`):'')}},
  {id:'tx3board', n:t(`看布告栏上的活儿`,`Check the bulletin board for work`,`Ver o quadro de anúncios`), cost:1, req:()=>S.flags.tx3_branding?t(`牧场烙印聚会的活已经接过了`,`You already took the branding-party job`,`Já aceitaste o trabalho da marcação do gado`):S.week>=6||t(`第 6 周以后`,`After week 6`,`Depois da semana 6`),
   run:()=>({title:t(`布告栏`,`The bulletin board`,`O quadro de anúncios`),meta:t(`外烩机会`,`A catering chance`,`Uma oportunidade de catering`),
    text:[t(`在丢失的山羊和出售的干草中间，有一张卡片：“春秋烙印聚会，四十人，要人烤肉。哈兰。”字迹很硬，你认得出来。`,`Between the lost goat and the hay for sale there's a card: "Branding party, forty head of people, need somebody to cook. Harlan." The handwriting is stiff. You recognise it.`,`Entre o bode perdido e o feno à venda há um cartão: «Marcação do gado, quarenta pessoas, precisa-se de quem grelhe. Harlan.» A letra é dura. Reconheces.`),
     t(`牧场烙印聚会是德州乡下的老规矩：一整天给小牛打烙印、打疫苗，邻居们都来帮手，干完了大家一起吃。`,`A branding is an old country custom: a whole day branding and vaccinating calves, neighbours all pitching in, and everybody eats together when it's done.`,`A marcação do gado é um velho costume do campo: um dia inteiro a marcar e vacinar vitelos, os vizinhos todos a ajudar, e no fim comem todos juntos.`)],
    choices:[
     {t:t(`接下：烤一整头猪的量`,`Take it: cook a whole hog's worth`,`Aceitar: grelhar o equivalente a um porco inteiro`),req:()=>S.inv.pork>=8||NEED(t(`库存猪肉 8`,`8 pork in stock`,`8 de porco em stock`)),fx:()=>{S.flags.tx3_branding=1;S.inv.pork-=8;S.cash+=280;S.wk.rev+=280;S.rep+=3;stat('tex',3);if(met('wade'))addTrust('wade',1)},next:()=>say(t(`烙印聚会`,`The branding`,`A marcação`),t(`你在牧场的畜栏边烤了一下午。韦德干完活走过来，吃了一盘，又吃了一盘，然后说了今天唯一一句话：“明年还你。”他的意思是明年还请你。`,`You grill all afternoon by the corrals. Wade comes over when the work's done, eats a plate, then another, and says his only words of the day: "You again next year." He means he'll hire you again.`,`Grelhas a tarde inteira junto aos currais. O Wade aparece quando acaba o trabalho, come um prato, depois outro, e diz as únicas palavras do dia: «Para o ano, tu outra vez.» Quer dizer que te contrata outra vez.`),t(`猪肉 −8 · 现金 +$280 · 口碑 +3 · 德州味 +3 · 韦德信任 +1`,`Pork −8 · Cash +$280 · Reputation +3 · Texanness +3 · Wade's trust +1`,`Porco −8 · Dinheiro +$280 · Reputação +3 · Texanidade +3 · Confiança do Wade +1`))},
     
     {t:t(`现在忙不过来，先不接`,`You're stretched thin — not now`,`Agora não dás conta — fica para outra`)}]})}
 ]},
 {id:'stadium', n:t(`高中橄榄球场`,`The high-school football stadium`,`O estádio de futebol americano do liceu`), open:()=>S.week>=2, acts:[
  {id:'tx3fnl', n:t(`周五夜灯：看比赛`,`Friday night lights: go to the game`,`Luzes de sexta à noite: ver o jogo`), cost:2, req:()=>!inSeason(13,24)?t(`橄榄球季在秋天（第 13–24 周）`,`Football season is in the fall (weeks 13–24)`,`A época é no outono (semanas 13–24)`):!(S.day===5&&S.slot===2)?t(`只在周五夜晚`,`Friday nights only`,`Só à sexta à noite`):true, tip:t(`全镇的人都在这里`,`The whole town is here`,`A vila inteira está aqui`),
   run:()=>{const hc=S.week===24,win=Math.random()<0.55;
    const ch=[
     {t:t(`在小卖部旁边支个摊`,`Set up a stand by the concession booth`,`Montar uma banca junto ao bar do estádio`),fx:()=>{},next:()=>{const r=popupSell(12,1.1);S.rep+=r.sold?2:0;stat('tex',1);return say(t(`看台下的烟`,`Smoke under the bleachers`,`Fumo debaixo das bancadas`),[t(`中场休息的时候，队伍排到了看台尽头。汤米和小戴尔在乐队里敲鼓，休息时跑过来帮你收钱，收得乱七八糟。`,`At halftime the line runs to the end of the bleachers. Tommy and Little Dale are drumming in the band; on their break they run over to help with the cash box and make a mess of it.`,`Ao intervalo a fila chega ao fim da bancada. O Tommy e o Little Dale tocam bombo na banda; no intervalo vêm ajudar com a caixa e fazem uma trapalhada.`),sellLine(r)],r.sold?t(`口碑 +2 · 德州味 +1`,`Reputation +2 · Texanness +1`,`Reputação +2 · Texanidade +1`):'')}}];
    if(met('ashley'))ch.unshift({t:t(`坐到教练席正后方，阿什莉那边`,`Sit right behind the bench, by Ashley`,`Sentar mesmo atrás do banco, ao pé da Ashley`),fx:()=>{addLike('ashley',1);addTrust('ashley',0.5);stat('charme',1)},next:()=>say(t(`教练席后面`,`Behind the bench`,`Atrás do banco`),win?t(`最后两分钟，阿什莉练出来的那个瘦小的跑卫一路冲进了达阵区。她回头找到你，拳头砸了一下自己的胸口。散场后她说：“身体不会撒谎。今晚他们的身体都说了真话。”`,`In the last two minutes the skinny running back Ashley trained breaks all the way into the end zone. She turns, finds you, and thumps her own chest once. After the game she says, "Bodies don't lie. Tonight every one of theirs told the truth."`,`Nos últimos dois minutos, o corredor franzino que a Ashley treinou corre até à zona de pontuação. Ela vira-se, encontra-te e bate uma vez no peito. No fim diz: «O corpo não mente. Esta noite o deles disse a verdade toda.»`):t(`输了七分。散场后阿什莉一个人坐在空看台上。你坐到她旁边，什么也没说。过了一会儿她说：“谢谢你没说‘下次会赢’。”`,`They lose by seven. After the game Ashley sits alone in the empty stands. You sit beside her and say nothing. After a while she says, "Thanks for not saying 'next time.'"`,`Perdem por sete. No fim, a Ashley fica sozinha na bancada vazia. Sentas-te ao lado dela sem dizer nada. Passado um bocado ela diz: «Obrigada por não dizeres "para a próxima".»`),t(`阿什莉好感 +1 · 信任 +0.5 · 魅力 +1`,`Ashley's affection +1 · trust +0.5 · Charm +1`,`Afeto da Ashley +1 · confiança +0,5 · Charme +1`))});
    return {title:t(`周五夜灯`,`Friday Night Lights`,`Luzes de sexta à noite`),meta:win?t(`圣鲁伊斯赢了`,`San Luís wins`,`San Luís ganha`):t(`圣鲁伊斯输了`,`San Luís loses`,`San Luís perde`),
     text:[t(`镇上九千人，球场能坐五千。周五夜里，整座小镇的灯好像都搬到了这里。所有人都穿着同一种颜色。`,`Nine thousand people in town, five thousand seats in the stadium. On Friday nights it's as if every light in town has moved here. Everyone's wearing the same color.`,`Nove mil habitantes, cinco mil lugares no estádio. À sexta à noite parece que todas as luzes da vila se mudaram para aqui. Estão todos vestidos da mesma cor.`),
      hc?t(`今晚是返校赛。女孩们胸前别着比脸还大的“菊花胸花”，缎带垂到膝盖，上面挂着小铃铛和男朋友的号码——这是德州高中的老传统，你第一次见，以为是什么奖牌。`,`Tonight is homecoming. The girls wear "mums" pinned to their chests, bigger than their faces, ribbons down to their knees, hung with little bells and their boyfriends' numbers. It's an old Texas high-school tradition. The first time you see one you think it's some kind of medal.`,`Esta noite é o regresso a casa. As raparigas trazem ao peito uns «crisântemos» maiores do que a cara, com fitas até aos joelhos, sininhos e o número do namorado — uma velha tradição dos liceus do Texas. Da primeira vez que vês um, achas que é uma medalha.`):pick([t(`空气里是爆米花、辣肉酱和割过的草的味道。`,`The air smells of popcorn, chili and cut grass.`,`O ar cheira a pipocas, chili e relva cortada.`),t(`开赛前全场起立唱国歌，然后是一段祷告。你低下头，想起圣安东尼教堂。`,`Before kickoff the whole stadium stands for the anthem, then a prayer. You bow your head and think of St. Anthony's.`,`Antes do pontapé de saída o estádio inteiro levanta-se para o hino, e depois uma oração. Baixas a cabeça e pensas na Igreja de Santo António.`)])],
     choices:ch}}},
  {id:'tx3booster', n:t(`给球队助威会做客场餐`,`Cater the booster club's away-game meal`,`Fazer a refeição do clube de apoio para o jogo fora`), cost:3, req:()=>S.flags.tx3_booster?t(`已经做过了`,`Already done`,`Já está feito`):S.week>=13||t(`第 13 周以后（橄榄球季）`,`From week 13 (football season)`,`A partir da semana 13 (época de futebol)`), tip:t(`一次性外烩订单`,`A one-off catering job`,`Uma encomenda de catering única`),
   run:()=>({title:t(`助威会`,`The booster club`,`O clube de apoio`),meta:t(`客场大巴，六十份`,`Away-game bus, sixty meals`,`Autocarro do jogo fora, sessenta refeições`),
    text:[t(`助威会会长是个嗓门很大的妈妈，她拿着一个写满名字的夹板进门：“下周客场，三个小时车程。六十个孩子，要吃饱，要好吃，不能太贵。阿什莉说你靠得住。”`,`The booster club president, a mom with a big voice, walks in with a clipboard full of names. "Away game next week, three hours on the bus. Sixty kids. Filling, tasty, not too pricey. Ashley says you're reliable."`,`A presidente do clube de apoio, uma mãe de voz forte, entra com uma prancheta cheia de nomes. «Jogo fora na semana que vem, três horas de autocarro. Sessenta miúdos. Que encha, que seja bom, que não seja caro. A Ashley diz que és de confiança.»`)],
    choices:[
     {t:t(`六十个猪排包，按正常价`,`Sixty pork sandwiches at full price`,`Sessenta bifanas ao preço normal`),req:()=>S.inv.pork>=10||NEED(t(`库存猪肉 10`,`10 pork in stock`,`10 de porco em stock`)),fx:()=>{S.flags.tx3_booster=1;S.inv.pork-=10;S.cash+=360;S.wk.rev+=360;S.rep+=2},next:()=>say(t(`大巴上的猪排包`,`Sandwiches on the bus`,`Bifanas no autocarro`),t(`第二天全镇都知道了：球队赢没赢不重要，大巴上的猪排包赢了。`,`By the next day the whole town knows: never mind whether the team won, the sandwiches on the bus did.`,`No dia seguinte a vila inteira sabe: ganhasse ou não a equipa, as bifanas do autocarro ganharam.`),t(`猪肉 −10 · 现金 +$360 · 口碑 +2`,`Pork −10 · Cash +$360 · Reputation +2`,`Porco −10 · Dinheiro +$360 · Reputação +2`))},
     {t:t(`按成本价做，再给每人加一个蛋挞`,`Do it at cost, plus a custard tart for every kid`,`Fazer a preço de custo, com um pastel de nata para cada miúdo`),req:()=>(S.inv.pork>=10&&S.inv.dairy>=6)||NEED(t(`库存猪肉 10、乳品 6`,`10 pork and 6 dairy in stock`,`10 de porco e 6 de lacticínios em stock`)),fx:()=>{S.flags.tx3_booster=1;S.inv.pork-=10;S.inv.dairy-=6;S.cash+=120;S.wk.rev+=120;S.rep+=6;S.online+=3;if(met('ashley'))addTrust('ashley',1)},next:()=>say(t(`六十个蛋挞`,`Sixty custard tarts`,`Sessenta pastéis de nata`),t(`孩子们在大巴上发了几十条视频，全是蛋挞。会长在家长群里写：“这个葡萄牙小伙子是我们的人。”阿什莉把截图发给你，什么也没写，只有一个大拇指。`,`The kids post dozens of videos from the bus, every one of them about the tarts. The president writes in the parents' group: "That Portuguese boy is one of ours." Ashley sends you the screenshot with no words, just a thumbs-up.`,`Os miúdos publicam dezenas de vídeos do autocarro, todos sobre os pastéis de nata. A presidente escreve no grupo dos pais: «Aquele rapaz português é dos nossos.» A Ashley manda-te a captura sem palavras, só um polegar para cima.`),t(`猪肉 −10 · 乳品 −6 · 现金 +$120 · 口碑 +6 · 线上评分 +3 · 阿什莉信任 +1`,`Pork −10 · Dairy −6 · Cash +$120 · Reputation +6 · Online +3 · Ashley's trust +1`,`Porco −10 · Lacticínios −6 · Dinheiro +$120 · Reputação +6 · Avaliação online +3 · Confiança da Ashley +1`))},
     {t:t(`婉拒，店里排不开`,`Decline — the shop can't spare the time`,`Recusar — o restaurante não tem mãos`),fx:()=>{S.rep-=1}}]})}
 ]},
 {id:'square', n:t(`法院广场`,`The courthouse square`,`A praça do tribunal`), open:()=>S.week>=3, acts:[
  {id:'tx3market', n:t(`周六农夫集市摆一张桌`,`A table at the Saturday farmers' market`,`Uma mesa no mercado de sábado`), cost:3, req:()=>S.day!==6?t(`只在周六`,`Saturdays only`,`Só ao sábado`):S.slot===2?t(`集市已经散了`,`The market's packed up`,`O mercado já fechou`):ONCE_DAY('mkt')(), tip:t(`从库存卖，略高于店价`,`Sells from stock, a bit above shop price`,`Vende do stock, um pouco acima do preço da casa`),
   run:()=>{markToday('mkt');const r=popupSell(10,1.25);
    return {title:t(`法院广场的周六`,`Saturday on the square`,`Sábado na praça`),meta:sellLine(r),
     text:[t(`县法院是一百多年前用本地石灰岩盖的，顶上有个钟楼，四面的钟走得都不太一样。周六早上，广场四边摆满了折叠桌：蜂蜜、山核桃、自家种的番茄、手工肥皂，还有你。`,`The county courthouse was built over a century ago from local limestone, with a clock tower whose four faces never quite agree. On Saturday mornings folding tables line all four sides of the square: honey, pecans, homegrown tomatoes, handmade soap — and you.`,`O tribunal do condado foi construído há mais de um século em calcário da região, com uma torre de relógio cujas quatro faces nunca estão de acordo. Aos sábados de manhã, mesas desdobráveis enchem os quatro lados da praça: mel, nozes-pecã, tomates da horta, sabão artesanal — e tu.`),
      pick([t(`一个老人在你桌前站了很久，问你会不会做“葡萄牙甜面包”，他外婆每年复活节都做。你说会，他眼睛红了。`,`An old man stands at your table a long while and asks if you can make Portuguese sweet bread; his grandmother made it every Easter. You say you can. His eyes go red.`,`Um velho fica muito tempo à tua mesa e pergunta se sabes fazer massa sovada; a avó dele fazia-a todas as Páscoas. Dizes que sim. Os olhos dele ficam vermelhos.`),t(`隔壁桌卖蜂蜜的大叔说今年的蜂蜜是牧豆树花的，跟你换了一份沙丁鱼。`,`The honey man at the next table says this year's is mesquite blossom honey, and trades you a jar for a sardine plate.`,`O homem do mel da mesa ao lado diz que este ano é mel de flor de algarobeira, e troca-te um frasco por um prato de sardinhas.`)])],
     choices:[
      {t:t(`跟隔壁花摊的萨凡纳拼桌`,`Share a table with Savannah's flower stall`,`Juntar a mesa à banca de flores da Savannah`),req:()=>met('savannah')||t(`先认识萨凡纳`,`Meet Savannah first`,`Conhece primeiro a Savannah`),fx:()=>{addLike('savannah',1);S.rep+=1},next:()=>say(t(`花和炭火`,`Flowers and coals`,`Flores e brasas`),t(`萨凡纳的向日葵挡住了你的烟，你的烟熏香了她的花。她说今天卖得比平时多一倍：“人家闻到肉香就饿，饿了就心软，心软就买花。”`,`Savannah's sunflowers shade your smoke, and your smoke perfumes her flowers. She says she sold twice as much as usual. "Folks smell meat, they get hungry; hungry makes 'em soft; soft makes 'em buy flowers."`,`Os girassóis da Savannah fazem sombra ao teu fumo, e o teu fumo perfuma as flores dela. Diz que vendeu o dobro do costume. «As pessoas cheiram a carne, ficam com fome; a fome amolece-as; amolecidas, compram flores.»`),t(`萨凡纳好感 +1 · 口碑 +1`,`Savannah's affection +1 · Reputation +1`,`Afeto da Savannah +1 · Reputação +1`))},
      
      {t:t(`收摊`,`Pack up`,`Arrumar a banca`)}]}}},
  {id:'tx3pruitt', n:t(`法院台阶上的普鲁伊特警长`,`Sheriff Pruitt on the courthouse steps`,`O xerife Pruitt nas escadas do tribunal`), cost:1, req:()=>S.week>=5||t(`第 5 周以后`,`After week 5`,`Depois da semana 5`), tip:t(`跟县里的法律打交道`,`Deal with the county's law`,`Lidar com a lei do condado`),
   run:()=>({title:t(`普鲁伊特警长`,`Sheriff Pruitt`,`O xerife Pruitt`),meta:t(`县法院`,`County courthouse`,`Tribunal do condado`),
    text:[t(`普鲁伊特警长坐在法院台阶上吃一个油纸包着的东西。他看见你，没站起来：“葡萄牙。坐。”`,`Sheriff Pruitt sits on the courthouse steps eating something out of wax paper. He sees you and doesn't get up. "Portugal. Sit."`,`O xerife Pruitt está sentado nas escadas do tribunal a comer qualquer coisa embrulhada em papel vegetal. Vê-te e não se levanta. «Portugal. Senta-te.»`),
     pick([t(`“你店门口那辆皮卡，停的是消防栓的位置。我今天没看见。明天我眼睛会好起来。”`,`"That pickup outside your shop is parked on the fire hydrant. Today I didn't see it. Tomorrow my eyes'll be better."`,`«A carrinha à porta do teu restaurante está em cima da boca de incêndio. Hoje não vi. Amanhã a vista já me volta.»`)])],
    choices:[
     {t:t(`送他一个猪排包当午饭`,`Bring him a pork sandwich for lunch`,`Levar-lhe uma bifana para o almoço`),req:()=>S.inv.pork>=1||NEED(t(`库存猪肉 1`,`1 pork in stock`,`1 de porco em stock`)),fx:()=>{S.inv.pork-=1;S.rep+=1;stat('tex',1)},next:()=>say(t(`午饭`,`Lunch`,`Almoço`),t(`他吃完舔了舔手指：“若泽以前也这样贿赂我。”他把帽子戴上，“有用。”`,`He finishes and licks his fingers. "José used to bribe me like this too." He puts his hat on. "It works."`,`Acaba e lambe os dedos. «O José também me subornava assim.» Põe o chapéu. «Resulta.»`),t(`口碑 +1 · 德州味 +1`,`Reputation +1 · Texanness +1`,`Reputação +1 · Texanidade +1`))},
     {t:t(`说实话：你还在学这里的规矩`,`Be honest: you're still learning the rules here`,`Ser honesto: ainda estás a aprender as regras daqui`),fx:()=>{stat('tex',2);S.rep+=0.5},next:()=>say(t(`规矩`,`The rules`,`As regras`),t(`“规矩就两条，”他说，“别撒谎，别在礼拜天早上放音乐。”他想了想，“第二条是我前妻定的。”`,`"Only two rules," he says. "Don't lie, and don't play music Sunday morning." He thinks. "Second one was my ex-wife's."`,`«Só há duas regras», diz ele. «Não mentir e não pôr música ao domingo de manhã.» Pensa um bocado. «A segunda foi a minha ex-mulher que inventou.»`),t(`德州味 +2`,`Texanness +2`,`Texanidade +2`))}]})},
  {id:'tx3memorial', n:t(`和厄尔在纪念碑前`,`At the memorial with Earl`,`No memorial com o Earl`), cost:1, req:()=>!met('earl')?t(`先认识厄尔`,`Meet Earl first`,`Conhece primeiro o Earl`):S.flags.tx3_memorial?t(`那个下午只有一次`,`That afternoon only happens once`,`Aquela tarde só acontece uma vez`):true, tip:t(`一次性`,`One-time`,`Uma vez só`),
   run:()=>{S.flags.tx3_memorial=1;
    return {title:t(`纪念碑`,`The memorial`,`O memorial`),meta:t(`法院广场的一角`,`A corner of the square`,`Um canto da praça`),
     text:[t(`广场一角有一块花岗岩纪念碑，刻着这个县历次战争里没回来的人。厄尔站在前面，摘了帽子，用拇指摸其中一个名字，摸了很久。你没问。`,`In one corner of the square stands a granite memorial carved with the county's men who didn't come back from its wars. Earl stands in front of it with his hat off, running his thumb over one name for a long time. You don't ask.`,`Num canto da praça há um memorial de granito com os nomes dos homens do condado que não voltaram das guerras. O Earl está de chapéu na mão, a passar o polegar por um nome, muito tempo. Não perguntas.`),
      t(`后来他指着下面一排：席尔瓦、梅洛、科斯塔、阿韦拉尔。“亚速尔人的孩子。若泽每年七月四号来这儿，一个一个念，用葡萄牙的念法。他说美国人念错了一辈子，总得有人念对一次。”`,`Then he points to a lower row: Silva, Mello, Costa, Avelar. "Azorean kids. José came every Fourth of July and read them out one by one, the Portuguese way. Said Americans had been saying 'em wrong their whole lives; somebody ought to say 'em right once."`,`Depois aponta para uma fila mais abaixo: Silva, Mello, Costa, Avelar. «Filhos de açorianos. O José vinha cá todos os quatro de julho e lia-os um a um, à portuguesa. Dizia que os americanos os pronunciaram mal a vida inteira; alguém tinha de os dizer bem uma vez.»`)],
     choices:[
      {t:t(`像若泽那样，把名字念一遍`,`Read the names out like José did`,`Ler os nomes como o José fazia`),fx:()=>{addTrust('earl',1);stat('saud',3);S.lusoThisWeek=true;S.rep+=1},next:()=>say(t(`念对一次`,`Said right, once`,`Ditos bem, uma vez`),t(`你一个一个念出来。念到第四个，厄尔把帽子戴回去，转身走了，走了几步说：“他念得没你好。别告诉他。”你们都知道没法告诉他了。`,`You read them out one by one. At the fourth, Earl puts his hat back on and turns away. A few steps off he says, "He didn't say 'em as good as you. Don't tell him." You both know there's no telling him now.`,`Lês um a um. Ao quarto, o Earl volta a pôr o chapéu e vira costas. Uns passos à frente diz: «Ele não os dizia tão bem como tu. Não lhe contes.» Ambos sabem que já não há como contar-lhe.`),t(`厄尔信任 +1 · 乡愁 +3 · 口碑 +1`,`Earl's trust +1 · Homesickness +3 · Reputation +1`,`Confiança do Earl +1 · Saudade +3 · Reputação +1`))},
      {t:t(`什么也不说，陪他站一会儿`,`Say nothing; just stand with him a while`,`Não dizer nada; ficar um bocado com ele`),fx:()=>{addTrust('earl',0.5);stat('tex',1)}}]}}}
 ]},
 
 {id:'diner', n:t(`公路加油站的小餐馆`,`The truck-stop diner on the highway`,`O restaurante da bomba de gasolina na autoestrada`), open:()=>true, acts:[
  {id:'tx3pie', n:t(`深夜咖啡和一块派`,`Late-night coffee and a slice of pie`,`Café da noite e uma fatia de tarte`), cost:1, req:()=>NIGHTONLY()===true?MONEY(6)():NIGHTONLY(), tip:t(`卡车司机的世界`,`The truckers' world`,`O mundo dos camionistas`),
   run:()=>{S.cash-=6;S.wk.spend+=6;
    return say(t(`凌晨的餐馆`,`The diner after midnight`,`O restaurante depois da meia-noite`),[
     t(`州际公路的辅路边有个二十四小时的加油站，后面连着一间小餐馆：红色的人造革卡座，一个转着的派柜，墙上的点唱机只放乡村老歌。`,`On the I-35 frontage road there's a twenty-four-hour gas station with a little diner out back: red vinyl booths, a rotating pie case, a jukebox that plays only old country.`,`Na via de serviço da I-35 há uma bomba de gasolina aberta vinte e quatro horas com um pequeno restaurante atrás: bancos de napa vermelha, uma vitrina de tartes a rodar, uma jukebox que só toca country antigo.`),
     pick([t(`隔壁卡座的卡车司机从拉雷多拉货到芝加哥，一年在路上三百天。他给你看手机里女儿的照片，然后问你：“你也是在路上的人吧？看得出来。”`,`The trucker in the next booth hauls from Laredo to Chicago, three hundred days a year on the road. He shows you his daughter's picture on his phone, then asks, "You're a road person too, ain't you? I can tell."`,`O camionista do banco ao lado leva carga de Laredo a Chicago, trezentos dias por ano na estrada. Mostra-te a foto da filha no telemóvel e pergunta: «Também és gente da estrada, não és? Nota-se.»`),t(`派是山核桃的，咖啡续了四次。窗外的卡车一辆接一辆，像一条亮着的河。你想到特茹河上的灯。`,`The pie is pecan and the coffee gets refilled four times. Outside the trucks go by one after another, like a lit river. You think of the lights on the Tagus.`,`A tarte é de noz-pecã e o café é reposto quatro vezes. Lá fora os camiões passam uns atrás dos outros, como um rio iluminado. Pensas nas luzes do Tejo.`)])],t(`−$6 · 乡愁 +2 · 德州味 +1`,`−$6 · Homesickness +2 · Texanness +1`,`−$6 · Saudade +2 · Texanidade +1`));}},
  {id:'tx3fly', n:t(`跟卡车司机拉生意`,`Drum up business with the truckers`,`Angariar clientes entre os camionistas`), cost:2, req:()=>S.flags.tx3_fly===S.week?t(`这周已经发过传单了`,`You've already handed out flyers this week`,`Já distribuíste folhetos esta semana`):true, tip:t(`口碑，看魅力`,`Reputation, scaled by Charm`,`Reputação, conforme o Charme`),
   run:()=>{S.flags.tx3_fly=S.week;
    return {title:t(`加油站的停车场`,`The truck-stop lot`,`O parque da bomba`),meta:t(`卡车司机`,`Truckers`,`Camionistas`),
     text:[t(`停车场上排着二十几辆半挂车，发动机都没熄。司机们在加油、洗挡风玻璃、站着抽烟。他们一年吃几百顿路边饭，知道三百英里内每一家值得下匝道的店。`,`Two dozen semis idle in the lot. Drivers fuel up, scrub windshields, stand around smoking. They eat hundreds of roadside meals a year and know every place within three hundred miles worth taking an exit for.`,`No parque há duas dezenas de camiões TIR com o motor a trabalhar. Os motoristas atestam, limpam para-brisas, fumam de pé. Comem centenas de refeições de estrada por ano e conhecem todos os sítios num raio de trezentas milhas que valem a saída.`)],
     choices:[
      {t:t(`挨个递传单，用你的口音`,`Hand out flyers one by one, accent and all`,`Dar folhetos um a um, com sotaque e tudo`),fx:()=>{const g=Math.round(1+charm()/30);S.rep+=g;stat('charme',1)},next:()=>say(t(`口音`,`The accent`,`O sotaque`),t(`一半的人以为你是意大利人，四分之一以为是巴西人。但他们都把传单塞进了遮阳板。下礼拜，店门口停了三辆半挂车。`,`Half of them think you're Italian, a quarter think Brazilian. But they all tuck the flyer into their sun visors. Next week three semis are parked outside your shop.`,`Metade acha que és italiano, um quarto acha que és brasileiro. Mas todos enfiam o folheto na pala do sol. Na semana seguinte, há três camiões TIR estacionados à porta do restaurante.`),t(`口碑上升 · 魅力 +1`,`Reputation up · Charm +1`,`Reputação sobe · Charme +1`))},
      {t:t(`带一盒猪排包，请他们尝`,`Bring a box of pork sandwiches to taste`,`Levar uma caixa de bifanas para provarem`),req:()=>S.inv.pork>=3||NEED(t(`库存猪肉 3`,`3 pork in stock`,`3 de porco em stock`)),fx:()=>{S.inv.pork-=3;S.rep+=3;S.online+=2;stat('tex',1)},next:()=>say(t(`对讲机`,`On the CB`,`No rádio`),t(`一个老司机咬了一口，拿起车里的对讲机说了几句。你听不懂那些暗语，但第二天，店里来了一个说“听电台里讲的”的人。`,`An old driver takes a bite, picks up the CB in his cab and says a few words. You don't follow the lingo, but the next day someone walks into the shop saying he "heard about it on the radio."`,`Um camionista velho dá uma dentada, pega no rádio da cabine e diz umas palavras. Não percebes a gíria, mas no dia seguinte entra alguém no restaurante a dizer que «ouviu falar disto no rádio».`),t(`猪肉 −3 · 口碑 +3 · 线上评分 +2 · 德州味 +1`,`Pork −3 · Reputation +3 · Online +2 · Texanness +1`,`Porco −3 · Reputação +3 · Avaliação online +2 · Texanidade +1`))}]}}}
 ]}
);

/* ================= ROAD EVENTS ================= */
const ROADT=c=>t(`路上`,`On the road`,`Na estrada`)+` · `+c.n;
ROAD_EVENTS.push(
 {id:'tx3_bluebonnet',cond:c=>inSeason(38,44),run:c=>{const w=W();
  return {title:t(`蓝帽花`,`Bluebonnets`,`Tremoceiros azuis`),meta:ROADT(c),
   text:[t(`公路两边忽然蓝了一大片。是蓝帽花，德州的州花，一种野生的羽扇豆。几十年前一位第一夫人推动在公路边撒野花种子，从那以后，每年春天德州的公路都会开成这样。`,`Suddenly both sides of the highway go blue. Bluebonnets, the state flower, a wild lupine. Decades ago a First Lady championed sowing wildflowers along the highways, and ever since, every spring, Texas roads bloom like this.`,`De repente as bermas ficam azuis. São tremoceiros azuis, a flor do estado, um tremoço selvagem. Há décadas uma primeira-dama defendeu que se semeassem flores silvestres nas bermas, e desde então, todas as primaveras, as estradas do Texas florescem assim.`),
    t(`路肩上停着好几辆车。一家人让穿着白裙子的小女儿坐在花里拍照——每个德州孩子小时候都有一张这样的照片。`,`Several cars are pulled onto the shoulder. One family sits their little girl in a white dress in the flowers for a photo — every Texas kid has a picture like this.`,`Há vários carros parados na berma. Uma família senta a filha pequena, de vestido branco, no meio das flores para uma foto — todas as crianças do Texas têm uma fotografia assim.`)],
   choices:[
    {t:t(`停车，坐进花里拍一张寄给妈妈`,`Pull over, sit in the flowers, send Mom a picture`,`Parar, sentar-te nas flores e mandar uma foto à mãe`),fx:()=>{stat('tex',2);stat('saud',-1);if(w)addLike(w,1)},next:()=>say(t(`德州的照片`,`A Texas picture`,`Uma fotografia do Texas`),w?t(`${SH(w)}帮你拍的，又非要挤进来再拍一张。妈妈回了一句：“这个人是谁？”`,`${SH(w)} takes it, then insists on squeezing in for another. Mom writes back: "Who is that?"`,`${SH(w)} tira a foto e depois insiste em entrar noutra. A mãe responde: «Quem é esta pessoa?»`):t(`妈妈回了一句：“你看起来像个德州人了。”你不知道这是夸你还是担心你。`,`Mom writes back: "You look like a Texan now." You can't tell if that's praise or worry.`,`A mãe responde: «Já pareces um texano.» Não sabes se é elogio ou preocupação.`),w?t(`德州味 +2 · 乡愁 −1 · ${SH(w)}好感 +1`,`Texanness +2 · Homesickness −1 · ${SH(w)} affection +1`,`Texanidade +2 · Saudade −1 · ${SH(w)}: afeto +1`):t(`德州味 +2 · 乡愁 −1`,`Texanness +2 · Homesickness −1`,`Texanidade +2 · Saudade −1`))},
    {t:t(`摇下车窗，慢慢开过去`,`Roll down the window and drive by slow`,`Abrir a janela e passar devagar`),fx:()=>stat('saud',1)}]}}},
 {id:'tx3_jam',cond:c=>['central','north'].includes(c.region),run:c=>({title:t(`35 号州际公路堵死了`,`I-35 is at a standstill`,`A I-35 está parada`),meta:ROADT(c),
   text:[t(`35 号州际公路又在修。三条车道并成一条，红色的刹车灯一直排到地平线。前面的皮卡后窗上贴着一张纸：“我出生的时候它就在修。”`,`I-35 is under construction again. Three lanes squeeze into one, and brake lights run red to the horizon. The pickup ahead has a sign in its back window: "It was under construction when I was born."`,`A I-35 está outra vez em obras. Três faixas apertam-se numa só e as luzes de travagem vão até ao horizonte. A carrinha da frente tem um papel no vidro de trás: «Já estava em obras quando eu nasci.»`)],
   choices:[
    {t:t(`开着收音机，跟着乡村电台唱`,`Turn on the radio and sing along with the country station`,`Ligar o rádio e cantar com a estação de country`),fx:()=>{stat('tex',2)},next:()=>say(t(`乡村电台`,`Country radio`,`Rádio country`),t(`四十分钟，你学会了三首歌的副歌。每首都关于卡车、母亲和一个离开的人。你发现它们和法多讲的是同一件事。`,`In forty minutes you learn three choruses. Every song is about a truck, a mother, and someone who left. You realise they're about the same thing fado is.`,`Em quarenta minutos aprendes três refrões. Todas as canções falam de uma carrinha, de uma mãe e de alguém que partiu. Percebes que falam do mesmo que o fado.`),t(`德州味 +2`,`Texanness +2`,`Texanidade +2`))},
    {t:t(`趁堵车回顾客的线上留言`,`Use the time to answer customers' online reviews`,`Aproveitar para responder às avaliações online`),fx:()=>{S.online+=2;S.energy=Math.max(0,S.energy-1)},next:()=>say(t(`回复`,`Replies`,`Respostas`),t(`你一条一条回。有人说蛋挞太甜，你说下次少放糖；有人说老板太帅，你没回。`,`You answer them one by one. Someone says the tarts are too sweet; you promise less sugar. Someone says the owner is too handsome; you leave that one alone.`,`Respondes uma a uma. Alguém diz que os pastéis são doces demais; prometes menos açúcar. Alguém diz que o dono é bonito demais; essa deixas sem resposta.`),t(`线上评分 +2 · 精力 −1`,`Online rating +2 · Energy −1`,`Avaliação online +2 · Energia −1`))}]})},
 {id:'tx3_flat',cond:c=>c.miles>=85,run:c=>{const car=canDrive();
  return {title:car?t(`爆胎`,`Flat tire`,`Pneu furado`):t(`巴士抛锚`,`The bus breaks down`,`O autocarro avaria`),meta:ROADT(c),
   text:[car?t(`砰的一声，方向盘往右一拽。你把皮卡停在路肩上，下车一看：右后轮扁得像一张饼。太阳毒得像在烤你。`,`A bang, and the wheel jerks right. You pull the pickup onto the shoulder and get out: the right rear tire is flat as a pancake. The sun feels like it's grilling you.`,`Um estoiro, e o volante puxa para a direita. Encostas a carrinha à berma e sais: o pneu traseiro direito está espalmado. O sol parece estar a grelhar-te.`):t(`巴士在一片棉花地边停下，司机说轮胎坏了，等救援，一个小时。乘客们下车站在唯一的一棵树下。`,`The bus stops beside a cotton field. The driver says it's a tire; help's an hour out. The passengers get off and stand under the only tree.`,`O autocarro para junto a um campo de algodão. O motorista diz que é um pneu; a assistência demora uma hora. Os passageiros saem e ficam debaixo da única árvore.`)],
   choices:car?[
    {t:t(`自己换备胎`,`Change it yourself`,`Mudar tu o pneu`),req:()=>S.course.drive>=3||S.stats.oficio>=40||NEED(t(`开车课 3 或手艺 40`,`Driving lesson 3 or Craft 40`,`3.ª aula de condução ou Ofício 40`)),fx:()=>{stat('tex',2);stat('oficio',1)},next:()=>say(t(`备胎`,`The spare`,`O pneu suplente`),t(`千斤顶、扳手、对角线拧螺丝——厄尔教过你。二十分钟，满手黑油。一辆路过的皮卡减速，司机看你弄好了，竖了个大拇指开走了。`,`Jack, lug wrench, tighten the nuts in a star — Earl taught you. Twenty minutes and black grease to the wrists. A passing pickup slows; seeing you've got it, the driver gives a thumbs-up and goes on.`,`Macaco, chave de rodas, apertar as porcas em cruz — o Earl ensinou-te. Vinte minutos e óleo preto até aos pulsos. Uma carrinha que passa abranda; o condutor vê que já está e segue com o polegar levantado.`),t(`德州味 +2 · 手艺 +1`,`Texanness +2 · Craft +1`,`Texanidade +2 · Ofício +1`))},
    {t:t(`打电话叫最近镇上的修车铺 $60`,`Call the nearest town's tire shop ($60)`,`Chamar a oficina da vila mais próxima ($60)`),req:MONEY(60),fx:()=>{S.cash-=60;S.wk.spend+=60},next:()=>say(t(`修车铺`,`The tire shop`,`A oficina`),t(`来的是个话很多的老头，换胎的时候给你讲了他三个前妻的故事。$60，故事免费。`,`A chatty old man shows up and tells you about his three ex-wives while he changes the tire. Sixty dollars; the stories are free.`,`Aparece um velhote falador que te conta as histórias das três ex-mulheres enquanto muda o pneu. Sessenta dólares; as histórias são de graça.`),t(`−$60`,`−$60`,`−$60`))}]:[
    {t:t(`跟树下的老太太聊天`,`Chat with the old lady under the tree`,`Conversar com a senhora debaixo da árvore`),fx:()=>{stat('tex',1);stat('saud',-1);stat('charme',1)},next:()=>say(t(`树下`,`Under the tree`,`Debaixo da árvore`),t(`她去看孙子，带了一整盒自己烤的饼干，分给所有人。她听说你开烧烤店，说下次路过一定去，还把你的店名写在饼干盒盖上。`,`She's on her way to see her grandson and passes around a whole tin of homemade cookies. When she hears you run a grill, she swears she'll stop by and writes the shop's name on the tin lid.`,`Vai visitar o neto e distribui uma caixa inteira de bolachas caseiras. Quando ouve que tens uma churrasqueira, jura que passa lá e escreve o nome do restaurante na tampa da caixa.`),t(`德州味 +1 · 乡愁 −1 · 魅力 +1`,`Texanness +1 · Homesickness −1 · Charm +1`,`Texanidade +1 · Saudade −1 · Charme +1`))},
    {t:t(`在树荫下打个盹`,`Nap in the shade`,`Dormir uma sesta à sombra`),fx:()=>{S.energy=Math.min(10,S.energy+1)}}]}}},
 
 {id:'tx3_pitstop',cond:c=>c.miles>=45,run:c=>({title:t(`巨型加油站`,`The giant gas station`,`A bomba de gasolina gigante`),meta:ROADT(c),
   text:[t(`公路边有一座大得像飞机库的加油站，一百多个加油枪，厕所干净得像医院，里面一整面墙的牛肉干，还有一个柜台在现切烟熏牛胸肉，切好就夹进面包里。`,`By the highway stands a gas station the size of an aircraft hangar: over a hundred pumps, restrooms clean as a hospital, an entire wall of jerky, and a counter carving smoked brisket straight onto buns.`,`À beira da estrada há uma bomba de gasolina do tamanho de um hangar: mais de cem bombas, casas de banho limpas como um hospital, uma parede inteira de carne seca e um balcão a fatiar peito de vaca fumado direto para o pão.`)],
   choices:[
    {t:t(`买一个牛胸肉三明治 $9`,`Buy a brisket sandwich ($9)`,`Comprar uma sanduíche de peito fumado ($9)`),req:MONEY(9),fx:()=>{S.cash-=9;stat('tex',2);stat('oficio',1)},next:()=>say(t(`对手`,`The competition`,`A concorrência`),t(`不错，真的不错。你一边吃一边在心里记：他们的面包是甜的，酱是另外给的。你决定回去试试。`,`Good. Really good. Eating, you take mental notes: sweet bun, sauce on the side. You decide to try it back home.`,`Bom. Mesmo bom. Enquanto comes, vais tomando notas de cabeça: pão adocicado, molho à parte. Decides experimentar em casa.`),t(`−$9 · 德州味 +2 · 手艺 +1`,`−$9 · Texanness +2 · Craft +1`,`−$9 · Texanidade +2 · Ofício +1`))},
    {t:t(`研究他们怎么让一百个加油枪同时不乱`,`Study how they run a hundred pumps without chaos`,`Estudar como põem cem bombas a funcionar sem caos`),fx:()=>{stat('oficio',2)},next:()=>say(t(`管理课`,`A lesson in management`,`Uma lição de gestão`),t(`每个员工只管一件事，每件事都有人管，而且每个人都在笑——至少假装在笑。你在餐巾纸上画了一张若泽烧烤店的新动线图。`,`Every worker does one thing, every thing has a worker, and everyone's smiling — or pretending to. On a napkin you sketch a new floor plan for Zé's.`,`Cada funcionário trata de uma coisa, cada coisa tem um funcionário, e estão todos a sorrir — ou a fingir. Num guardanapo desenhas um novo circuito para a Churrasqueira do Zé.`),t(`手艺 +2`,`Craft +2`,`Ofício +2`))}]})},
 {id:'tx3_trooper',cond:c=>canDrive(),run:c=>({title:t(`州警`,`State trooper`,`Polícia estadual`),meta:ROADT(c),
   text:[t(`后视镜里红蓝灯一闪。一位戴宽檐帽的州警走过来，敲了敲车窗：“限速七十五，你开到八十二。驾照。”你递上葡萄牙驾照和国际驾照。他看了很久。`,`Red and blue in the mirror. A state trooper in a wide-brimmed hat walks up and taps the window. "Limit's seventy-five, you were doing eighty-two. License." You hand over your Portuguese license and the international permit. He studies them a long time.`,`Luzes vermelhas e azuis no espelho. Um polícia estadual de chapéu de abas largas aproxima-se e bate no vidro. «O limite é setenta e cinco, ia a oitenta e dois. Carta.» Entregas a carta portuguesa e a licença internacional. Ele examina-as muito tempo.`)],
   choices:[
    {t:t(`老老实实认错`,`Own up, plain and simple`,`Assumir o erro, sem rodeios`),fx:()=>{if(Math.random()<0.6){stat('tex',1)}else{S.cash-=120;S.wk.spend+=120}},next:()=>say(t(`认错`,`Owning up`,`Assumir`),t(`“你至少没说‘我不知道’，”他说，“一百个人里九十个这么说。”他最后给了你一张警告单，或者罚单——取决于他今天的心情。`,`"At least you didn't say 'I didn't know,'" he says. "Ninety out of a hundred do." In the end you get a warning, or a ticket — depending on his mood today.`,`«Ao menos não disse "não sabia"», diz ele. «Noventa em cem dizem.» No fim leva um aviso, ou uma multa — conforme o humor dele hoje.`),t(`可能罚 $120`,`Possible $120 fine`,`Possível multa de $120`))},
    {t:t(`用最正式的英语解释`,`Explain yourself in your most formal English`,`Explicar-te no inglês mais formal possível`),req:()=>S.accent!=='浓'||t(`口音太重，越解释越糟`,`Your accent's too thick — explaining will make it worse`,`O sotaque é forte demais — explicar só piora`),fx:()=>{stat('charme',1)},next:()=>say(t(`警告单`,`A warning`,`Um aviso`),t(`他听完点点头，撕了一张警告单给你：“欢迎来德州，先生。这里的路很长，别急着走完。”`,`He hears you out, nods, and tears off a warning. "Welcome to Texas, sir. Roads are long here. No need to finish 'em all at once."`,`Ouve-te, acena e arranca uma folha de aviso. «Bem-vindo ao Texas, senhor. As estradas aqui são compridas. Não precisa de as acabar todas de uma vez.»`),t(`只是警告 · 魅力 +1`,`Just a warning · Charm +1`,`Só um aviso · Charme +1`))}]})},
 
 {id:'tx3_storm',run:c=>({title:t(`雷暴`,`Thunderstorm`,`Trovoada`),meta:ROADT(c),
   text:[t(`西南边的天空忽然变成了青紫色，像一块淤青。十分钟后，雨砸下来，雨刷开到最快也看不见前面。收音机里在播冰雹警告。`,`The southwest sky turns a greenish purple, like a bruise. Ten minutes later the rain hits; even at full speed the wipers can't clear the glass. The radio is broadcasting a hail warning.`,`O céu a sudoeste fica de um roxo esverdeado, como uma nódoa negra. Dez minutos depois a chuva desaba; nem com o limpa-vidros no máximo se vê nada. O rádio dá um aviso de granizo.`)],
   choices:[
    {t:t(`开进下一个出口，在教堂停车场等`,`Take the next exit and wait it out in a church parking lot`,`Sair na próxima saída e esperar no parque de uma igreja`),fx:()=>{stat('tex',1);S.energy=Math.min(10,S.energy+1)},next:()=>say(t(`等雨停`,`Waiting it out`,`À espera`),t(`冰雹砸在车顶上像有人往上面倒弹珠。二十分钟后一切停了，太阳出来，路面冒着白气，空气里是湿泥土和牧豆树的味道。`,`Hail hammers the roof like someone pouring marbles on it. Twenty minutes later it's over: the sun's out, the road steams, and the air smells of wet earth and mesquite.`,`O granizo bate no tejadilho como berlindes despejados. Vinte minutos depois acabou: sai o sol, o asfalto fumega e o ar cheira a terra molhada e algarobeira.`),t(`德州味 +1 · 精力 +1`,`Texanness +1 · Energy +1`,`Texanidade +1 · Energia +1`))},
    {t:t(`打开双闪，慢慢往前挪`,`Hazards on, creep forward`,`Ligar os quatro piscas e avançar devagar`),fx:()=>{if(Math.random()<0.3){S.cash-=80;S.wk.spend+=80}stat('tex',1)},next:()=>say(t(`闯过去`,`Pushing through`,`Seguir em frente`),t(`你攥着方向盘，手心全是汗。冲出雨区的时候，你回头看了一眼，那片云像一座黑色的城堡，还在原地。也许挡风玻璃上多了一道冰雹砸的裂纹。`,`You grip the wheel, palms slick. Coming out the far side you glance back: the cloud sits there like a black castle. There may be a new hail crack in your windshield.`,`Agarras o volante com as mãos a suar. Ao sair do aguaceiro olhas para trás: a nuvem continua lá, como um castelo negro. Talvez haja uma nova racha de granizo no para-brisas.`),t(`德州味 +1 · 可能修车 $80`,`Texanness +1 · Possible $80 repair`,`Texanidade +1 · Possível reparação de $80`))}]})},
 {id:'tx3_kolache',cond:c=>c.region==='north'&&c.miles>100,run:c=>({title:t(`西镇的捷克果馅包`,`Kolaches in West`,`Kolaches em West`),meta:ROADT(c),
   text:[t(`过了韦科往北二十英里，有个叫西镇的小地方。十九世纪末一批捷克移民在这里落脚，留下了果馅包：软软的甜面包，中间放杏子或奶酪。往北开的人都在这里下高速排队。`,`Twenty miles north of Waco there's a little place called West. Czech immigrants settled here in the late 1800s and left behind the kolache: a soft sweet bun with apricot or cream cheese in the middle. Everybody heading north pulls off here and queues.`,`Vinte milhas a norte de Waco há uma terra chamada West. Imigrantes checos instalaram-se aqui no fim do século XIX e deixaram o kolache: um pão doce e macio com alperce ou queijo-creme no meio. Quem vai para norte sai aqui e faz fila.`)],
   choices:[
    {t:t(`不下高速，直接开过去`,`Skip the exit and drive on`,`Não sair da autoestrada e seguir`),fx:()=>stat('saud',1)},
    {t:t(`问店里的老太太，她外婆是怎么来的`,`Ask the old woman at the counter how her grandmother came here`,`Perguntar à senhora do balcão como veio a avó dela`),fx:()=>{stat('saud',2);stat('tex',1);stat('oficio',1)},next:()=>say(t(`另一个移民的故事`,`Another immigrant's story`,`A história de outra emigrante`),t(`“坐船到加尔维斯顿，再坐马车。一句英语也不会。她带来的只有面粉的做法。”她把面团摔在案板上，“一百多年了，我们还在做她的面包。你们葡萄牙人也一样吧？”你说一样。`,`"Boat to Galveston, then a wagon. Not a word of English. All she brought was how to make the dough." She slaps the dough on the board. "Over a hundred years and we're still making her bread. Same with you Portuguese, I bet?" You say it's the same.`,`«De barco até Galveston, depois de carroça. Nem uma palavra de inglês. Só trouxe a maneira de fazer a massa.» Bate com a massa na bancada. «Mais de cem anos e ainda fazemos o pão dela. Com vocês portugueses é igual, aposto?» Dizes que é igual.`),t(`乡愁 +2 · 德州味 +1 · 手艺 +1`,`Homesickness +2 · Texanness +1 · Craft +1`,`Saudade +2 · Texanidade +1 · Ofício +1`))}]})},
 {id:'tx3_westroad',cond:c=>c.region==='west',run:c=>({title:t(`往西的空路`,`The empty road west`,`A estrada vazia para oeste`),meta:ROADT(c),
   text:[t(`过了佩科斯河，十号州际公路上一个小时也碰不到一辆车，四周只有平顶的方山和风车。手机信号没了。`,`Past the Pecos you can go an hour on I-10 without meeting a car; all around, only flat-topped mesas and windmills. The phone signal dies.`,`Depois do Pecos pode-se fazer uma hora na I-10 sem cruzar um carro; à volta, só mesetas de topo plano e moinhos. O telemóvel perde a rede.`)],
   choices:[
    {t:t(`关掉收音机，听这片安静`,`Switch off the radio and listen to the quiet`,`Desligar o rádio e ouvir o silêncio`),fx:()=>{stat('saud',-2);S.energy=Math.min(10,S.energy+1)},next:()=>say(t(`安静`,`Quiet`,`Silêncio`),t(`只有轮胎和风。你突然明白若泽为什么从来不回家了——不是不想，是走得太远以后，回头的路比来的路长。你决定，你不要让自己的路变成那样。`,`Just tires and wind. Suddenly you understand why José never went home — not because he didn't want to, but because once you've gone far enough, the road back is longer than the road out. You decide you won't let yours get like that.`,`Só pneus e vento. De repente percebes porque é que o José nunca voltou — não por não querer, mas porque, depois de ires longe o suficiente, o caminho de volta é mais comprido do que o de ida. Decides que o teu não vai ficar assim.`),t(`乡愁 −2 · 精力 +1`,`Homesickness −2 · Energy +1`,`Saudade −2 · Energia +1`))},
    {t:t(`在野餐区停下，给家里打个电话`,`Stop at a picnic area and call home`,`Parar numa área de piquenique e ligar para casa`),fx:()=>{stat('saud',3)},next:()=>say(t(`一格信号`,`One bar`,`Uma barra de rede`),t(`野餐区的水泥棚子下面有一格信号。里斯本是晚上，妈妈接了，声音断断续续。你只听清了一句：“……你那边天是什么颜色？”你说：“很大。”她说：“那就好。”`,`Under the concrete shelter at the picnic area there's one bar. It's evening in Lisbon; Mom picks up, breaking up. You only catch one line: "...what color is the sky there?" You say, "Big." She says, "Good, then."`,`Debaixo do abrigo de cimento da área de piquenique há uma barra. Em Lisboa é noite; a mãe atende, a voz aos soluços. Só percebes uma frase: «…de que cor é o céu aí?» Dizes: «Grande.» Ela diz: «Então está bem.»`),t(`乡愁 +3`,`Homesickness +3`,`Saudade +3`))}]})}
);
})();
